/* candidate algorithm */
static void luafmt(char *buff, size_t n, double v, const char *first) {
  int len = snprintf(buff, n, first, v);
  if (strtod(buff, NULL) != v) {           /* not a round trip? */
    len = snprintf(buff, n, "%.17g", v);
  }
  if (buff[strspn(buff, "-0123456789")] == '\0') { /* looks like an int? */
    buff[len++] = '.'; buff[len++] = '0'; buff[len] = '\0';
  }
}
int main(int argc, char**argv){
  const char *first = argc>1?argv[1]:"%.15g";
  char line[256]; char buf[80];
  while (fgets(line,sizeof line,stdin)) {
    char *nl=strchr(line,'\n'); if(nl)*nl=0;
    if(!*line) continue;
    double v = strtod(line,NULL);
    luafmt(buf,sizeof buf,v,first);
    printf("%s\n", buf);
  }
  return 0;
}
