#include <string.h>
#include <math.h>
#include <stdlib.h>
typedef int64_t I; typedef uint64_t U; typedef double N;
static I idiv(I m, I n){ /* Lua luaV_idiv */
  if ((U)(n)+1u <= 1u){ if(n==0){printf("!DIVZERO");return 0;} return (I)(0u - (U)m); }
  { I q = m/n; if ((m^n) < 0 && m%n != 0) q -= 1; return q; }
}
static I imod(I m, I n){
  if ((U)(n)+1u <= 1u){ if(n==0){printf("!MODZERO");return 0;} return 0; }
  { I r = m%n; if (r != 0 && (r^n) < 0) r += n; return r; }
}
static N nmod(N a, N b){ N m = fmod(a,b); if ((m>0) ? b<0 : (m<0 && b>0)) m += b; return m; }
static N nidiv(N a, N b){ return floor(a/b); }
static void pf(char*buf,size_t n,N v){ int len=snprintf(buf,n,"%.15g",v); if(strtod(buf,NULL)!=v) len=snprintf(buf,n,"%.17g",v); if(buf[strspn(buf,"-0123456789")]=='\0'){buf[len++]='.';buf[len++]='0';buf[len]=0;} }
