typedef int64_t I; typedef double N;
#define TWO63 9223372036854775808.0
/* exact mathematical comparisons between int64 and double */
static int eq_if(I i, N f){ if(!(f>=-TWO63 && f<TWO63)) return 0; if(floor(f)!=f) return 0; return (I)f==i; }
static int lt_if(I i, N f){ if(isnan(f)) return 0; if(f>=TWO63) return 1; if(f<-TWO63) return 0;
  /* i < f  <=>  i < ceil(f) when f not integral, else i < (I)f */
  { N c = ceil(f); if (c>=TWO63) return 1; { I fi=(I)c; return (c==f)? (i<fi) : (i<fi); } } }
static int le_if(I i, N f){ if(isnan(f)) return 0; if(f>=TWO63) return 1; if(f<-TWO63) return 0;
  { N fl = floor(f); I fi=(I)fl; return i<=fi; } }
static int lt_fi(N f, I i){ if(isnan(f)) return 0; if(f>=TWO63) return 0; if(f<-TWO63) return 1;
  { N fl=floor(f); I fi=(I)fl; return (fl==f)? (fi<i) : (fi<i); } }
static int le_fi(N f, I i){ if(isnan(f)) return 0; if(f>=TWO63) return 0; if(f<-TWO63) return 1;
  { N c=ceil(f); if(c>=TWO63) return 0; { I fi=(I)c; return fi<=i; } } }
