/* model of luaB_tonumber with base (5.4 b_str2int) */
static const char *b_str2int (const char *s, unsigned base, int64_t *pn) {
  uint64_t n = 0; int neg = 0;
  while (isspace((unsigned char)*s)) s++;
  if (*s == '-') { s++; neg = 1; } else if (*s == '+') s++;
  if (!isalnum((unsigned char)*s)) return NULL;
  do {
    int digit = (int)(isdigit((unsigned char)*s) ? *s - '0'
                   : (toupper((unsigned char)*s) - 'A') + 10);
    if ((unsigned)digit >= base) return NULL;
    n = n * base + (unsigned)digit;
    s++;
  } while (isalnum((unsigned char)*s));
  while (isspace((unsigned char)*s)) s++;
  if (*s != '\0') return NULL;
  *pn = (int64_t)(neg ? (uint64_t)0 - n : n);
  return s;
}
int main(void){ char line[512];
  while (fgets(line,sizeof line,stdin)) {
    char *nl=strchr(line,'\n'); if(nl)*nl=0;
    char *sp=strrchr(line,' '); if(!sp) continue; *sp=0;
    unsigned base = (unsigned)atoi(sp+1);
    int64_t v; if (b_str2int(line, base, &v)) printf("%lld\n",(long long)v); else printf("nil\n");
  }
  return 0; }
